import { pgTable, serial, text, numeric, timestamp, integer, boolean } from 'drizzle-orm/pg-core';

// 1. የተጠቃሚዎች ቴብል
export const users = pgTable('users', {
  id: serial('id').primaryKey(),
  fullName: text('full_name').notNull(),
  phone: text('phone').notNull().unique(),
  address: text('address'),
  role: text('role').default('buyer'), // 'buyer' | 'seller'
  createdAt: timestamp('created_at').defaultNow(),
});

// 2. የምርቶች (Products) ቴብል
export const products = pgTable('products', {
  id: serial('id').primaryKey(),
  sellerId: integer('seller_id').references(() => users.id),
  title: text('title').notNull(),
  price: numeric('price').notNull(),
  category: text('category').notNull(),
  description: text('description'),
  photoUrl: text('photo_url').notNull(),
  videoUrl: text('video_url'),
  createdAt: timestamp('created_at').defaultNow(),
});

// 3. የክፍያ እና Escrow ቴብል
export const transactions = pgTable('transactions', {
  id: serial('id').primaryKey(),
  txRef: text('tx_ref').notNull().unique(),
  buyerId: integer('buyer_id').references(() => users.id),
  productId: integer('product_id').references(() => products.id),
  amount: numeric('amount').notNull(),
  status: text('status').default('PENDING'), // 'PENDING' | 'HELD_IN_ESCROW' | 'RELEASED' | 'DISPUTED'
  otpCode: text('otp_code').notNull(),
  createdAt: timestamp('created_at').defaultNow(),
});

// 4. የቻት መልእክቶች ቴብል
export const messages = pgTable('messages', {
  id: serial('id').primaryKey(),
  senderId: integer('sender_id').references(() => users.id),
  receiverId: integer('receiver_id').references(() => users.id),
  message: text('message').notNull(),
  createdAt: timestamp('created_at').defaultNow(),
});
